const grant = $json;

const clean = (value) =>
  (value ?? '')
    .toString()
    .trim();

const errors = [];

if (!clean(grant.grant_id)) {
  errors.push('Missing grant_id');
}

if (!clean(grant.organization_id)) {
  errors.push('Missing organization_id');
}

if (!clean(grant.foundation_name)) {
  errors.push('Missing foundation_name');
}

if (!clean(grant.program_name)) {
  errors.push('Missing program_name');
}

if (clean(grant.status).toLowerCase() !== 'new') {
  errors.push('Status must be New');
}

const validationStatus =
  errors.length === 0 ? 'Valid' : 'Invalid';

return {
  json: {
    ...grant,
    validation_status: validationStatus,
    validation_errors: errors.join(', '),
    validated_at: new Date().toISOString(),
  },
};

const grant = $json;

// --------------------------------------------------
// LOAD ORGANIZATION PROFILE
// --------------------------------------------------

const organizations = $('Read Organization Profile from Sheets')
  .all()
  .map(item => item.json)
  .filter(row => row && Object.keys(row).length > 0);

let score = 0;
const reasons = [];

// --------------------------------------------------
// HELPERS
// --------------------------------------------------

const clean = (value) =>
  (value || '')
    .toString()
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

const normalizeYesNo = (value) =>
  clean(value);

const parseList = (value) =>
  (value || '')
    .toString()
    .split(/[;,|]/)
    .map(item => clean(item))
    .filter(Boolean);

const normalizePhrase = (value) => {
  const text = clean(value);

  return text
    .replace(/\bcampaigns\b/g, 'campaign')
    .replace(/\bscholarships\b/g, 'scholarship')
    .replace(/\bgrants\b/g, 'grant');
};

// --------------------------------------------------
// MATCH GRANT WITH ORGANIZATION PROFILE
// --------------------------------------------------

const organization = organizations.find(
  org =>
    clean(org.organization_id) ===
    clean(grant.organization_id)
);

const organizationFound = Boolean(organization);

if (!organizationFound) {
  reasons.push(
    `Organization profile not found for ${
      grant.organization_id || 'missing organization_id'
    }`
  );
}

// --------------------------------------------------
// GRANT TEXT USED FOR MATCHING
// --------------------------------------------------

const grantText = clean(`
  ${grant.foundation_name || ''}
  ${grant.program_name || ''}
  ${grant.program_areas || ''}
  ${grant.foundation_mission || ''}
  ${grant.eligibility || ''}
  ${grant.geographic_focus || ''}
  ${grant.recent_grantees || ''}
  ${grant.notes || ''}
`);

// --------------------------------------------------
// ORGANIZATION-DRIVEN CONFIGURATION
// --------------------------------------------------

const priorityKeywords = organization
  ? parseList(organization.priority_programs)
  : [];

const excludedGrantTypes = organization
  ? parseList(organization.excluded_grant_types)
  : [];

const targetGeographies = organization
  ? [
      ...parseList(organization.primary_geography),
      ...parseList(organization.state),
      ...parseList(organization.country),
    ].filter(Boolean)
  : [];

// --------------------------------------------------
// INFORMATIONAL SIGNALS
// --------------------------------------------------

if (clean(grant.website)) {
  reasons.push('Foundation website available');
}

if (clean(grant.application_url)) {
  reasons.push('Application page available');
}

// --------------------------------------------------
// 1. PROGRAM / MISSION ALIGNMENT
// Maximum: +35
//
// Public-template logic:
// Matching is driven entirely by the nonprofit's
// priority_programs field in the Organization Profile.
// --------------------------------------------------

const matchedKeywords = priorityKeywords.filter(
  keyword =>
    keyword &&
    grantText.includes(keyword)
);

const uniqueMatchedKeywords = [
  ...new Set(matchedKeywords),
];

let alignmentScore = 0;

if (uniqueMatchedKeywords.length >= 3) {
  alignmentScore = 35;
} else if (uniqueMatchedKeywords.length >= 1) {
  alignmentScore = 25;
}

if (alignmentScore > 0) {
  score += alignmentScore;

  reasons.push(
    `Priority program alignment: ${uniqueMatchedKeywords.join(', ')}`
  );

  reasons.push(
    `Program alignment score: +${alignmentScore}`
  );
} else if (
  organizationFound &&
  priorityKeywords.length === 0
) {
  reasons.push(
    'No priority programs configured for organization'
  );
} else {
  reasons.push(
    'No meaningful program alignment identified'
  );
}

// --------------------------------------------------
// 2. GEOGRAPHIC FIT
// Maximum: +20
//
// Uses the organization's configured geography.
// No organization-specific state is hard-coded.
// --------------------------------------------------

const grantGeography = clean(
  grant.geographic_focus
);

const broadGeographyTerms = [
  'national',
  'nationwide',
  'countrywide',
];

const directGeographicMatch =
  Boolean(grantGeography) &&
  targetGeographies.some(
    geography =>
      geography &&
      (
        grantGeography.includes(geography) ||
        geography.includes(grantGeography)
      )
  );

const broadGeographicMatch =
  Boolean(grantGeography) &&
  targetGeographies.length > 0 &&
  broadGeographyTerms.some(
    term =>
      grantGeography.includes(term)
  );

const geographicMatch =
  Boolean(grantGeography) &&
  (
    directGeographicMatch ||
    broadGeographicMatch
  );

if (geographicMatch) {
  score += 20;

  reasons.push(
    'Geographic fit'
  );

  reasons.push(
    'Geographic fit score: +20'
  );
}

// Only call something a mismatch when:
// 1. Organization profile exists
// 2. Organization has geography configured
// 3. Grant geography is known
// 4. No configured geography matches

const geographicMismatch =
  organizationFound &&
  targetGeographies.length > 0 &&
  Boolean(grantGeography) &&
  !geographicMatch;

if (geographicMismatch) {
  reasons.push(
    `Geographic mismatch: ${grant.geographic_focus}`
  );
}

// --------------------------------------------------
// 3. GRANT AMOUNT
//
// Informational in this public template.
// Users can customize this later based on their
// organization's preferred award range.
// --------------------------------------------------

if (grant.grant_amount) {
  reasons.push(
    'Grant amount available for review'
  );
}

// --------------------------------------------------
// 4. PREVIOUS FUNDER RELATIONSHIP
// +25
// --------------------------------------------------

if (
  normalizeYesNo(
    grant.previous_funder
  ) === 'yes'
) {
  score += 25;

  reasons.push(
    'Previous funder relationship'
  );

  reasons.push(
    'Previous funder score: +25'
  );
}

// --------------------------------------------------
// 5. NEW APPLICANTS ALLOWED
// +10
// --------------------------------------------------

if (
  normalizeYesNo(
    grant.new_applicants_allowed
  ) === 'yes'
) {
  score += 10;

  reasons.push(
    'New applicants allowed'
  );

  reasons.push(
    'New applicant score: +10'
  );
}

// --------------------------------------------------
// 6. ROLLING DEADLINE
// +5
// --------------------------------------------------

if (
  normalizeYesNo(
    grant.rolling_deadline
  ) === 'yes'
) {
  score += 5;

  reasons.push(
    'Rolling deadline'
  );

  reasons.push(
    'Rolling deadline score: +5'
  );
}

// --------------------------------------------------
// 7. INVITATION-ONLY RESTRICTION
// -25
// --------------------------------------------------

const invitationOnly =
  normalizeYesNo(
    grant.invitation_only
  ) === 'yes';

if (invitationOnly) {
  score -= 25;

  reasons.push(
    'Invitation-only restriction'
  );

  reasons.push(
    'Invitation-only adjustment: -25'
  );
}

// --------------------------------------------------
// ELIGIBILITY TEXT
// --------------------------------------------------

const eligibilityText = clean(
  grant.eligibility
);

// --------------------------------------------------
// 8. REAPPLICATION / TIMING RESTRICTIONS
// --------------------------------------------------

const timingRestrictionTerms = [
  'must wait',
  'cannot reapply',
  'can not reapply',
  'waiting period',
  'reapply after',
  'wait at least',
  'not eligible to reapply',
];

const timingRestriction =
  timingRestrictionTerms.some(
    term =>
      eligibilityText.includes(term)
  );

if (timingRestriction) {
  reasons.push(
    'Reapplication timing restriction requires verification'
  );
}

// --------------------------------------------------
// 9. APPLICANT ACCESS RESTRICTIONS
// --------------------------------------------------

const applicantAccessRestrictionTerms = [
  'not accepting new applications',
  'no longer accepting new applications',
  'not accepting introductory applications',
  'no longer accepting introductory applications',
  'closed to new applicants',
  'existing grantees only',
  'current grantees only',
  'only open to existing applicants',
  'only open to current grantees',
  'renewal grants only',
  'renewals only',
];

const applicantAccessRestriction =
  applicantAccessRestrictionTerms.some(
    term =>
      eligibilityText.includes(term)
  );

if (applicantAccessRestriction) {
  reasons.push(
    'Applicant access restriction: not currently open to new applicants'
  );
}

// --------------------------------------------------
// 10. GENERAL ELIGIBILITY VERIFICATION FLAGS
//
// These do not automatically reject a grant.
// They tell the reviewer that a condition should
// be checked manually.
// --------------------------------------------------

const verificationRequirementTerms = [
  'matching funds required',
  'matching contribution required',
  'cost share required',
  'audit required',
  'letters of support required',
  'letter of support required',
  'fiscal sponsor required',
  'partnership required',
  'collaboration required',
];

const matchedVerificationRequirements =
  verificationRequirementTerms.filter(
    term =>
      eligibilityText.includes(term)
  );

const verificationRequirement =
  matchedVerificationRequirements.length > 0;

if (verificationRequirement) {
  reasons.push(
    `Eligibility requirement requires verification: ${matchedVerificationRequirements.join(', ')}`
  );
}

// --------------------------------------------------
// 11. ORGANIZATION-CONFIGURED EXCLUSIONS
//
// Each nonprofit controls this using
// excluded_grant_types in its Organization Profile.
// --------------------------------------------------

const normalizedGrantText =
  normalizePhrase(grantText);

const matchedExclusions =
  excludedGrantTypes.filter(
    excludedType =>
      normalizedGrantText.includes(
        normalizePhrase(excludedType)
      )
  );

const excludedGrant =
  matchedExclusions.length > 0;

if (excludedGrant) {
  reasons.push(
    `Excluded grant type: ${matchedExclusions.join(', ')}`
  );
}

// --------------------------------------------------
// KEEP SCORE BETWEEN 0 AND 100
// --------------------------------------------------

score = Math.max(
  0,
  Math.min(100, score)
);

// --------------------------------------------------
// PRIORITY
//
// These are example public-template thresholds.
// Users can customize them for their organization.
// --------------------------------------------------

let priority = 'Low';

if (score >= 75) {
  priority = 'Hot';
} else if (score >= 50) {
  priority = 'Warm';
}

// --------------------------------------------------
// FIT RATING
// --------------------------------------------------

let fitRating = 'Not Applicable';

if (score >= 85) {
  fitRating = 'Great';
} else if (score >= 65) {
  fitRating = 'Good';
} else if (score >= 50) {
  fitRating = 'OK';
} else if (score >= 30) {
  fitRating = 'Uncertain';
} else if (score >= 11) {
  fitRating = 'Poor';
}

// --------------------------------------------------
// BASE RECOMMENDATION
// --------------------------------------------------

let recommendation =
  'Do not prioritize';

if (score >= 75) {
  recommendation =
    'Prioritize for detailed review';
} else if (score >= 50) {
  recommendation =
    'Ready for team review';
} else if (score >= 30) {
  recommendation =
    'Research further before deciding';
}

// --------------------------------------------------
// SAFETY / REVIEW OVERRIDES
// --------------------------------------------------

// Missing organization profile

if (!organizationFound) {
  priority = 'Low';
  fitRating = 'Uncertain';

  recommendation =
    'Manual review required — organization profile was not found';
}

// Invitation only

if (invitationOnly) {
  recommendation =
    'Verify invitation or funder relationship before pursuing';
}

// Timing restriction

if (timingRestriction) {
  priority = 'Low';
  fitRating = 'Uncertain';

  recommendation =
    'Verify reapplication timing before pursuing';
}

// Applicant access restriction

if (applicantAccessRestriction) {
  priority = 'Low';
  fitRating = 'Poor';

  recommendation =
    'Do not prioritize — opportunity is not currently open to new applicants';
}

// Geographic mismatch

if (geographicMismatch) {
  score = 0;
  priority = 'Low';
  fitRating = 'Not Applicable';

  recommendation =
    'Do not prioritize — outside configured geographic scope';
}

// Organization-configured exclusion

if (excludedGrant) {
  score = 0;
  priority = 'Low';
  fitRating = 'Not Applicable';

  recommendation =
    `Do not prioritize — excluded grant type: ${matchedExclusions.join(', ')}`;
}

// --------------------------------------------------
// RESEARCH COMPLETENESS
//
// Core fields used to determine whether enough
// information exists to trust the recommendation.
// --------------------------------------------------

const completenessFields = {
  eligibility: clean(
    grant.eligibility
  ),

  geographic_focus: clean(
    grant.geographic_focus
  ),

  program_areas: clean(
    grant.program_areas
  ),

  foundation_mission: clean(
    grant.foundation_mission
  ),

  recent_grantees: clean(
    grant.recent_grantees
  ),
};

const completedResearchFields =
  Object.values(completenessFields)
    .filter(value => Boolean(value))
    .length;

let researchCompleteness =
  'Insufficient';

if (completedResearchFields >= 4) {
  researchCompleteness =
    'Complete';
} else if (completedResearchFields >= 2) {
  researchCompleteness =
    'Partial';
}

const missingResearchFields =
  Object.entries(completenessFields)
    .filter(([, value]) => !value)
    .map(([field]) => field);

if (
  researchCompleteness === 'Partial'
) {
  reasons.push(
    `Research completeness: Partial (${completedResearchFields}/5 core fields completed)`
  );
}

if (
  researchCompleteness === 'Insufficient'
) {
  reasons.push(
    `Research completeness: Insufficient (${completedResearchFields}/5 core fields completed)`
  );
}

// --------------------------------------------------
// INSUFFICIENT RESEARCH SAFEGUARD
//
// Important:
// This does NOT automatically change the score.
// It warns the reviewer not to rely on an
// incomplete evaluation.
// --------------------------------------------------

if (
  researchCompleteness === 'Insufficient' &&
  !geographicMismatch &&
  !excludedGrant &&
  !applicantAccessRestriction
) {
  recommendation =
    `${recommendation} — More research required before relying on this score`;
}

// --------------------------------------------------
// FINAL OUTPUT
// --------------------------------------------------

return {
  json: {
    ...grant,

    organization_name:
      organization?.organization_name || '',

    organization_profile_found:
      organizationFound,

    matched_priority_keywords:
      uniqueMatchedKeywords.join(', '),

    // Kept for compatibility with existing
    // downstream Grant Master columns.
    matched_program_concepts:
      uniqueMatchedKeywords.join(', '),

    matched_exclusions:
      matchedExclusions.join(', '),

    geographic_match:
      geographicMatch,

    geographic_mismatch:
      geographicMismatch,

    timing_restriction:
      timingRestriction,

    applicant_access_restriction:
      applicantAccessRestriction,

    // Generic public template does not use
    // organization-specific conditional-fit rules.
    conditional_fit_restriction:
      false,

    conditional_fit_terms:
      '',

    verification_requirement:
      verificationRequirement,

    verification_requirements:
      matchedVerificationRequirements.join(', '),

    research_completeness:
      researchCompleteness,

    research_fields_completed:
      completedResearchFields,

    missing_research_fields:
      missingResearchFields.join(', '),

    score_version:
      'public-template-v1.0',

    grant_score:
      score,

    priority,

    fit_rating:
      fitRating,

    score_reasons:
      reasons.join(', '),

    recommendation,

    status:
      'Scored',

    updated_at:
      new Date().toISOString(),
  },
};

const grant = $json;

// --------------------------------------------------
// BASIC DISPLAY FIELDS
// --------------------------------------------------

const foundationName =
  grant.foundation_name || 'Unknown foundation';

const programName =
  grant.program_name || 'Unnamed grant program';

const score =
  Number(grant.grant_score || 0);

const priority =
  grant.priority || 'Low';

const fitRating =
  grant.fit_rating || 'Uncertain';

const reasons =
  grant.score_reasons || 'No scoring reasons available';

const recommendation =
  grant.recommendation || 'Review manually';

const deadline =
  grant.deadline || 'Not provided';

const grantAmount =
  grant.grant_amount || 'Not provided';

const applicationUrl =
  grant.application_url ||
  grant.website ||
  'Not provided';

const reviewerNotes =
  grant.notes || '';

const researchCompleteness =
  grant.research_completeness ||
  'Unknown';

const missingResearchFields =
  grant.missing_research_fields ||
  'None listed';

const eligibilityChecklist = [
  `Eligibility: ${grant.eligibility || 'Not provided'}`,
  `Geographic Fit: ${
    grant.geographic_mismatch === true
      ? 'Mismatch'
      : grant.geographic_match === true
      ? 'Match'
      : 'Needs Review'
  }`,
  `Invitation Only: ${grant.invitation_only || 'Not provided'}`,
  `New Applicants Allowed: ${
    grant.new_applicants_allowed || 'Not provided'
  }`,
  `Research Completeness: ${researchCompleteness}`,
].join('\n');

// --------------------------------------------------
// RECOMMENDATION SUMMARY
// --------------------------------------------------

const recommendation_summary =
`${foundationName} — ${programName}

Grant Score: ${score}
Priority: ${priority}
Fit Rating: ${fitRating}

Recommendation:
${recommendation}

Why:
${reasons}

Eligibility Checklist:
${eligibilityChecklist}

Deadline:
${deadline}

Grant Amount:
${grantAmount}

Application URL:
${applicationUrl}

Missing Research Fields:
${missingResearchFields}

Research Notes:
${reviewerNotes}`;

// --------------------------------------------------
// DEADLINE STATUS
// --------------------------------------------------

let deadlineStatus =
  'No Deadline';

const rolling =
  (grant.rolling_deadline || '')
    .toString()
    .toLowerCase()
    .trim();

const deadlineValue =
  (grant.deadline || '')
    .toString()
    .trim();

if (rolling === 'yes') {
  deadlineStatus =
    'Rolling';
} else if (!deadlineValue) {
  deadlineStatus =
    'No Deadline';
} else if (
  [
    'tbd',
    'tba',
    'waiting for deadline',
  ].includes(
    deadlineValue.toLowerCase()
  )
) {
  deadlineStatus =
    'Waiting for Deadline';
} else {
  const deadlineDate =
    new Date(deadlineValue);

  if (
    Number.isNaN(
      deadlineDate.getTime()
    )
  ) {
    deadlineStatus =
      'Waiting for Deadline';
  } else {
    const today =
      new Date();

    today.setHours(
      0,
      0,
      0,
      0
    );

    deadlineDate.setHours(
      0,
      0,
      0,
      0
    );

    const daysUntilDeadline =
      Math.ceil(
        (deadlineDate - today) /
        (1000 * 60 * 60 * 24)
      );

    if (
      daysUntilDeadline < 0
    ) {
      deadlineStatus =
        'Deadline Passed';
    } else if (
      daysUntilDeadline <= 14
    ) {
      deadlineStatus =
        'Deadline Soon';
    } else {
      deadlineStatus =
        'Upcoming';
    }
  }
}

// --------------------------------------------------
// ELIGIBILITY STATUS
//
// Public-template-safe logic:
// No state, country, or nonprofit type is hard-coded.
// Uses signals already produced by Score Grant Fit.
// --------------------------------------------------

let eligibilityStatus =
  'Needs Review';

const eligibilityText =
  (grant.eligibility || '')
    .toString()
    .toLowerCase()
    .trim();

const geographicMismatch =
  grant.geographic_mismatch === true;

const geographicMatch =
  grant.geographic_match === true;

const applicantAccessRestriction =
  grant.applicant_access_restriction === true;

const timingRestriction =
  grant.timing_restriction === true;

const excludedGrant =
  Boolean(
    (grant.matched_exclusions || '')
      .toString()
      .trim()
  );

if (
  eligibilityText.includes(
    'not eligible'
  ) ||
  eligibilityText.includes(
    'ineligible'
  ) ||
  geographicMismatch ||
  excludedGrant
) {
  eligibilityStatus =
    'Not Eligible';
} else if (
  applicantAccessRestriction
) {
  eligibilityStatus =
    'Not Currently Accessible';
} else if (
  timingRestriction
) {
  eligibilityStatus =
    'Conditional';
} else if (
  geographicMatch &&
  eligibilityText
) {
  eligibilityStatus =
    'Likely Eligible';
} else if (
  eligibilityText.includes(
    'eligible'
  )
) {
  eligibilityStatus =
    'Likely Eligible';
} else if (
  eligibilityText.includes(
    'uncertain'
  ) ||
  eligibilityText.includes(
    'review'
  )
) {
  eligibilityStatus =
    'Uncertain';
}

// --------------------------------------------------
// RESEARCH STAGE
// --------------------------------------------------

let researchStage =
  'Grant Found';

if (
  eligibilityStatus ===
    'Not Eligible' ||
  deadlineStatus ===
    'Deadline Passed'
) {
  researchStage =
    'Closed';
} else if (
  eligibilityStatus ===
    'Needs Review' ||
  eligibilityStatus ===
    'Uncertain' ||
  eligibilityStatus ===
    'Conditional' ||
  eligibilityStatus ===
    'Not Currently Accessible' ||
  researchCompleteness ===
    'Insufficient'
) {
  researchStage =
    'Grant Analysis Needed';
} else if (
  eligibilityStatus ===
    'Likely Eligible'
) {
  researchStage =
    'Ready for Review';
}

// --------------------------------------------------
// WORKFLOW STATUS
// --------------------------------------------------

let workflowStatus =
  'Not Started';

if (
  researchStage ===
    'Closed'
) {
  workflowStatus =
    'Completed';
} else if (
  researchStage ===
    'Ready for Review' ||
  researchStage ===
    'Grant Analysis Needed'
) {
  workflowStatus =
    'In Progress';
}

// --------------------------------------------------
// REVIEW STATUS
// --------------------------------------------------

let reviewStatus =
  'Not Reviewed';

if (
  researchStage ===
    'Ready for Review' ||
  researchStage ===
    'Grant Analysis Needed'
) {
  reviewStatus =
    'Needs Review';
}

// --------------------------------------------------
// APPLICATION STATUS
//
// Public template does not auto-approve or
// automatically move a grant to application.
// Human review remains required.
// --------------------------------------------------

const applicationStatus =
  'Not Started';

// --------------------------------------------------
// FINAL STATUS
// --------------------------------------------------

const finalStatus =
  researchStage ===
    'Closed'
    ? 'Closed'
    : 'Ready for Review';

// --------------------------------------------------
// FINAL OUTPUT
// --------------------------------------------------

return {
  json: {
    ...grant,

    recommendation_summary,

    status:
      finalStatus,

    deadline_status:
      deadlineStatus,

    eligibility_status:
      eligibilityStatus,

    research_stage:
      researchStage,

    workflow_status:
      workflowStatus,

    review_status:
      reviewStatus,

    application_status:
      applicationStatus,

    updated_at:
      new Date().toISOString(),
  },
};

const existingGrants = items
  .map(item => item.json)
  .filter(row => row && Object.keys(row).length > 0);

const clean = (value) =>
  (value || '')
    .toString()
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

const buildDuplicateKey = (grant) => {
  const organizationId = clean(grant.organization_id);
  const foundationName = clean(grant.foundation_name);
  const programName = clean(grant.program_name);

  if (!foundationName || !programName) {
    return '';
  }

  return `${organizationId}||${foundationName}||${programName}`;
};

// Get only VALID incoming grants
let queueGrants = [];

try {
  queueGrants = $('Execute Grant Validation Code')
    .all()
    .map(item => item.json)
    .filter(grant => grant.validation_status === 'Valid');
} catch (error) {
  queueGrants = [];
}

// Existing Grant Master duplicate keys
const seenGrantKeys = new Set(
  existingGrants
    .map(buildDuplicateKey)
    .filter(Boolean)
);

// Existing Grant Master grant IDs
const seenGrantIds = new Set(
  existingGrants
    .map(grant => clean(grant.grant_id))
    .filter(Boolean)
);

// Grant IDs already encountered during this execution
const batchGrantIds = new Set();

return queueGrants.map((grant) => {
  const duplicateKey = buildDuplicateKey(grant);
  const grantId = clean(grant.grant_id);

  let duplicate = false;
  let duplicateReason = '';

  // First protect the unique grant_id
  if (grantId && seenGrantIds.has(grantId)) {
    duplicate = true;
    duplicateReason =
      'Duplicate grant_id already exists in Grant Master';
  } else if (grantId && batchGrantIds.has(grantId)) {
    duplicate = true;
    duplicateReason =
      'Duplicate grant_id found within the same workflow batch';
  } else if (!duplicateKey) {
    duplicate = false;
    duplicateReason =
      'Duplicate check skipped because foundation name or program name is missing';
  } else if (seenGrantKeys.has(duplicateKey)) {
    duplicate = true;
    duplicateReason =
      'Duplicate organization, foundation, and program';
  } else {
    seenGrantKeys.add(duplicateKey);
  }

  if (grantId) {
    batchGrantIds.add(grantId);
  }

  return {
    json: {
      ...grant,
      duplicate,
      duplicate_text: duplicate ? 'yes' : 'no',
      duplicateReason,
      duplicate_key: duplicateKey,
      created_at:
        grant.created_at || new Date().toISOString(),
      updated_at: new Date().toISOString(),
    },
  };
});
